export const InvoiceModal: React.FC<InvoiceModalProps> = ({ isOpen, onClose, dues }) => {
  if (!isOpen || dues.length === 0) return null;

  const handlePrint = () => {
      const printContent = document.getElementById('invoice-printable-area');
      if (!printContent) return;

      // Open a new dedicated window for printing
      const printWindow = window.open('', '_blank', 'width=1000,height=800');

      if (!printWindow) {
          alert("Por favor, permita pop-ups para imprimir.");
          return;
      }

      const htmlContent = `
        <!DOCTYPE html>
        <html lang="pt-BR">
        <head>
            <meta charset="UTF-8">
            <title>Imprimir Faturas</title>
            <script src="https://cdn.tailwindcss.com"></script>
            <style>
                @page { size: A4; margin: 10mm; }
                body { 
                    background-color: white; 
                    -webkit-print-color-adjust: exact; 
                    print-color-adjust: exact; 
                }
                .water-bill-container {
                    break-inside: avoid;
                    page-break-after: always;
                    margin-bottom: 2rem;
                }
                .water-bill-container:last-child {
                    page-break-after: auto;
                }
            </style>
        </head>
        <body class="p-4">
            ${printContent.innerHTML}
            <script>
                // Wait for Tailwind to load, then print
                setTimeout(() => {
                    window.print();
                    // Optional: window.close();
                }, 1000);
            </script>
        </body>
        </html>
      `;

      printWindow.document.write(htmlContent);
      printWindow.document.close();
  };

  const exportToCSV = () => {
    const csvHeader = "Nº Fatura;Sócio;Endereço;Referência;Vencimento;Leitura Ant.;Leitura Atual;Consumo m3;Valor R$;Status";
    const csvRows = dues.map(bill => {
        return [
            bill.invoiceNumber || '',
            `"${bill.memberName}"`,
            `"${bill.memberAddress || ''}"`,
            `${bill.month}/${bill.year}`,
            new Date(bill.dueDate).toLocaleDateString('pt-BR'),
            bill.readingDetails?.previousReading || 0,
            bill.readingDetails?.currentReading || 0,
            bill.readingDetails?.consumption || 0,
            bill.amount.toFixed(2).replace('.', ','),
            bill.status
        ].join(';');
    });

    const csvContent = "\uFEFF" + [csvHeader, ...csvRows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Relatorio_Faturas_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title={dues.length > 1 ? `Faturas (${dues.length})` : "Fatura"}>
      <div className="bg-blue-50 border border-blue-200 p-4 rounded-md mb-4 print:hidden">
          <h4 className="font-bold text-blue-800 text-sm mb-2 flex items-center gap-2">
            <PrinterIcon className="w-4 h-4" />
            Como Salvar na Nuvem ou Imprimir?
          </h4>
          <ol className="list-decimal list-inside text-sm text-blue-900 space-y-1 ml-1">
            <li>Clique no botão <strong>Imprimir ou Salvar PDF</strong> abaixo.</li>
            <li>Uma nova janela se abrirá com a visualização de impressão.</li>
            <li>Em "Destino", selecione <strong>"Salvar como PDF"</strong>.</li>
            <li>O arquivo gerado será compatível com WhatsApp, E-mail e Google Drive.</li>
          </ol>
      </div>

      <div className="flex justify-between items-center mb-4 gap-2">
         <button onClick={exportToCSV} className="text-sm text-gray-600 hover:text-gray-800 underline flex items-center gap-1">
            <DownloadIcon className="w-4 h-4" />
            Baixar Planilha (Excel/CSV)
         </button>
         <button onClick={handlePrint} className="px-6 py-3 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 flex items-center gap-2 shadow-md transition-transform transform active:scale-95">
            <PrinterIcon className="w-5 h-5" />
            Imprimir ou Salvar PDF
        </button>
      </div>

      {/* Hidden container just to hold the HTML for extraction */}
      <div id="invoice-printable-area" className="bg-gray-100 p-4 rounded-lg overflow-auto max-h-[60vh] border border-gray-300">
        {dues.map((due) => (
            <WaterBill key={due.id} due={due} />
        ))}
      </div>

      <div className="flex justify-end p-4 border-t mt-4">
        <button onClick={onClose} className="px-6 py-2 bg-gray-200 text-gray-800 font-medium rounded-md hover:bg-gray-300">Fechar</button>
      </div>
    </Modal>
  );
};

