    setDues(prev => [...prev, ...newDues]);
  };

  const replaceMonthlyDues = (month: string, year: number, newDues: MembershipDue[]) => {
    setDues(prev => {
        const others = prev.filter(d => !(d.month === month && d.year === year));
        return [...others, ...newDues];
