    setDues(data.dues);
    setExpenses(data.expenses);
    setMeetings(data.meetings);
  };

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard':
        return <DashboardPage members={members} dues={dues} meetings={meetings} />;
      case 'members':
        return <MembersPage members={members} onAddMember={addMember} onUpdateMember={updateMember} />;
      case 'readings':
        return <WaterReadingsPage 
                    members={members} 
                    dues={dues} 
                    onAddDues={addDues} 
                    onSyncDues={replaceMonthlyDues}
                    waterPrice={waterPrice}
                    serviceFee={serviceFee}
                    setWaterPrice={setWaterPrice}
                    setServiceFee={setServiceFee}
                />;
      case 'financials':
        return <FinancialsPage dues={dues} expenses={expenses} onUpdateExpenseStatus={updateExpenseStatus} onAddExpense={addExpense} onUpdateDueStatus={updateDueStatus} />;
      case 'calendar':
        return <CalendarPage meetings={meetings} onAddMeeting={addMeeting} />;
      case 'backup':
        return <BackupPage data={{ members, dues, expenses, meetings }} onRestore={handleRestore} />;
      default:
        return <DashboardPage members={members} dues={dues} meetings={meetings} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <DashboardIcon className="w-5 h-5"/> },
    { id: 'members', label: 'Sócios', icon: <UsersIcon className="w-5 h-5"/> },
    { id: 'readings', label: 'Leituras e Faturas', icon: <WaterDropIcon className="w-5 h-5"/> },
    { id: 'financials', label: 'Financeiro', icon: <DollarSignIcon className="w-5 h-5"/> },
    { id: 'calendar', label: 'Calendário', icon: <CalendarIcon className="w-5 h-5"/> },
  ];

  const settingsNavItem = {
    id: 'backup', label: 'Backup e Dados', icon: <CogIcon className="w-5 h-5" />
  };

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <aside className="w-64 bg-blue-900 text-white flex flex-col p-4">
        <div className="text-center py-4 mb-6">
          <h2 className="text-lg font-bold">ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS</h2>
          <p className="text-xs text-blue-300">Gestão de Água</p>
        </div>
        <nav className="flex-1 flex flex-col justify-between">
            <div className="space-y-2">
                {navItems.map(item => (
                     <NavItem
                        key={item.id}
                        label={item.label}
                        icon={item.icon}
                        isActive={activeView === item.id}
                        onClick={() => setActiveView(item.id as View)}
                    />
                ))}
            </div>
            <div>
                <NavItem
                    key={settingsNavItem.id}
                    label={settingsNavItem.label}
                    icon={settingsNavItem.icon}
                    isActive={activeView === settingsNavItem.id}
                    onClick={() => setActiveView(settingsNavItem.id as View)}
                />
            </div>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto">
        {renderContent()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Member, MembershipDue, PaymentStatus, WaterReadingDetails } from '../types';
import { SearchIcon, WaterDropIcon, CogIcon, CalendarIcon, DownloadIcon, PlusIcon, DollarSignIcon, UploadIcon, PrinterIcon, SaveIcon } from './Icons';
import { InvoiceModal } from './InvoiceModal';
import Modal from './common/Modal';
import { importedData } from '../App';

interface WaterReadingsPageProps {
  members: Member[];
  dues: MembershipDue[];
  onAddDues: (newDues: MembershipDue[]) => void;
  onSyncDues: (month: string, year: number, newDues: MembershipDue[]) => void;
  waterPrice: number;
  serviceFee: number;
  setWaterPrice: (price: number) => void;
  setServiceFee: (fee: number) => void;
}

const getMonthName = (monthIndex: number) => {
    const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
    return months[monthIndex];
};

interface ReadingHistoryModalProps {
    isOpen: boolean;
    onClose: () => void;
    member: Member | null;
    dues: MembershipDue[];
}

const ReadingHistoryModal: React.FC<ReadingHistoryModalProps> = ({ isOpen, onClose, member, dues }) => {
    if (!isOpen || !member) return null;

    const history = dues
        .filter(d => d.memberId === member.id && d.readingDetails)
        .sort((a, b) => {
             if (a.year !== b.year) return b.year - a.year;
             const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
             return months.indexOf(b.month) - months.indexOf(a.month);
        });

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={`Histórico de Consumo: ${member.name}`}>
            <div className="max-h-[60vh] overflow-y-auto">
                {history.length === 0 ? (
                    <div className="text-center py-8 text-gray-500">
                        <WaterDropIcon className="w-12 h-12 mx-auto mb-2 text-gray-300" />
                        <p>Nenhum histórico de leitura encontrado para este sócio.</p>
                    </div>
                ) : (
                    <table className="w-full text-sm text-left text-gray-500">
                        <thead className="text-xs text-gray-700 uppercase bg-gray-100 sticky top-0">
                            <tr>
                                <th className="px-4 py-3 rounded-tl-lg">Referência</th>
                                <th className="px-4 py-3 text-center">Leitura Ant.</th>
                                <th className="px-4 py-3 text-center">Leitura Atual</th>
                                <th className="px-4 py-3 text-center">Consumo</th>
                                <th className="px-4 py-3 text-right rounded-tr-lg">Valor</th>
                            </tr>
                        </thead>
                        <tbody>
                            {history.map((record) => (
                                <tr key={record.id} className="bg-white border-b hover:bg-gray-50">
                                    <td className="px-4 py-3 font-medium text-gray-900">
                                        {record.month}/{record.year}
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        {record.readingDetails?.previousReading}
                                    </td>
                                    <td className="px-4 py-3 text-center font-bold text-gray-700">
                                        {record.readingDetails?.currentReading}
                                    </td>
                                    <td className="px-4 py-3 text-center">
                                        <span className="bg-blue-100 text-blue-800 text-xs font-bold px-2.5 py-0.5 rounded">
                                            {record.readingDetails?.consumption} m³
                                        </span>
                                    </td>
                                    <td className="px-4 py-3 text-right font-medium">
                                        R$ {record.amount.toFixed(2)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>
            <div className="mt-4 flex justify-end">
                <button 
                    onClick={onClose}
                    className="px-4 py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300 transition-colors"
                >
                    Fechar
                </button>
            </div>
        </Modal>
    );
};

export const WaterReadingsPage: React.FC<WaterReadingsPageProps> = ({ 
    members, 
    dues, 
    onAddDues,
    onSyncDues,
    waterPrice,
    serviceFee,
    setWaterPrice,
    setServiceFee
}) => {
  // Ajustado para Dezembro de 2024 como padrão
  const [selectedDate, setSelectedDate] = useState(new Date(2024, 11, 1)); 
  const [customDueDate, setCustomDueDate] = useState('2025-01-10');
  const [searchTerm, setSearchTerm] = useState('');
  const [readings, setReadings] = useState<Record<string, { current: string, previous: string }>>({});
  const [generatedDues, setGeneratedDues] = useState<MembershipDue[]>([]);
  const [isInvoiceModalOpen, setIsInvoiceModalOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [selectedHistoryMember, setSelectedHistoryMember] = useState<Member | null>(null);
  const [energyBill, setEnergyBill] = useState<string>('');
  const [startInvoiceNumber, setStartInvoiceNumber] = useState<number>(1);

  const monthStr = getMonthName(selectedDate.getMonth());
  const year = selectedDate.getFullYear();

  const existingBills = useMemo(() => 
      dues.filter(d => d.month === monthStr && d.year === year), 
      [dues, monthStr, year]
  );

  useEffect(() => {
    const nextMonth = new Date(selectedDate);
    nextMonth.setMonth(nextMonth.getMonth() + 1);
    nextMonth.setDate(10);
    setCustomDueDate(nextMonth.toISOString().split('T')[0]);
  }, [selectedDate]);

  useEffect(() => {
    if (dues.length > 0) {
        const maxInvoiceNum = dues.reduce((max, due) => {
            return (due.invoiceNumber && due.invoiceNumber > max) ? due.invoiceNumber : max;
        }, 0);
        setStartInvoiceNumber(maxInvoiceNum + 1);
    } else {
        setStartInvoiceNumber(1);
    }
  }, [dues]);

  useEffect(() => {
    const prevDate = new Date(selectedDate);
    prevDate.setMonth(prevDate.getMonth() - 1);
    const prevMonthStr = getMonthName(prevDate.getMonth());
    const prevYear = prevDate.getFullYear();

    const initialReadings: Record<string, { current: string, previous: string }> = {};
    const draftKey = `readings_draft_${year}_${monthStr}`;
    const savedDraftStr = localStorage.getItem(draftKey);
    const savedDraft = savedDraftStr ? JSON.parse(savedDraftStr) : {};

    members.forEach(member => {
        const existingBill = dues.find(d => d.memberId === member.id && d.month === monthStr && d.year === year);
        const prevBill = dues.find(d => d.memberId === member.id && d.month === prevMonthStr && d.year === prevYear);
        const lastReading = prevBill?.readingDetails?.currentReading ?? member.initialReading ?? 0;

        let prevVal = lastReading.toString();
        let currVal = '';

        if (existingBill?.readingDetails) {
            prevVal = existingBill.readingDetails.previousReading.toString();
            currVal = existingBill.readingDetails.currentReading.toString();
        } else if (savedDraft[member.id]) {
            prevVal = savedDraft[member.id].previous || prevVal;
            currVal = savedDraft[member.id].current || '';
        }

        initialReadings[member.id] = {
            previous: prevVal,
            current: currVal
        };
    });
    setReadings(initialReadings);
  }, [members, dues, selectedDate, monthStr, year]);

  useEffect(() => {
    const draftKey = `readings_draft_${year}_${monthStr}`;
    if (Object.keys(readings).length > 0) {
        localStorage.setItem(draftKey, JSON.stringify(readings));
    }
  }, [readings, year, monthStr]);

  const handleReadingChange = (memberId: string, field: 'current' | 'previous', value: string) => {
    setReadings(prev => ({
        ...prev,
        [memberId]: {
            ...prev[memberId],
            [field]: value
        }
    }));
  };

  // Função especial para preencher os dados de Dezembro baseados na lista fornecida
  const handleSeedDecemberData = () => {
    if (monthStr !== 'Dezembro' || year !== 2024) {
        const confirm = window.confirm("Você não está no período de Dezembro/2024. Deseja mudar para Dezembro/2024 e preencher as leituras da lista?");
        if (confirm) {
            setSelectedDate(new Date(2024, 11, 1));
        } else {
            return;
        }
    }

    const newReadings = { ...readings };
    let count = 0;

    importedData.forEach(data => {
        const member = members.find(m => m.name.toUpperCase() === data.name.toUpperCase());
        if (member) {
            newReadings[member.id] = {
                previous: data.prev.toString(),
                current: data.curr.toString()
            };
            count++;
        }
    });

    setReadings(newReadings);
    alert(`${count} leituras de Dezembro preenchidas com sucesso! Clique em "Gerar Faturas" para processar.`);
  };

  const handleSaveDraft = () => {
      const draftKey = `readings_draft_${year}_${monthStr}`;
      localStorage.setItem(draftKey, JSON.stringify(readings));
      alert("Leituras salvas com sucesso!");
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleImportReadings = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        const text = e.target?.result as string;
        if (!text) return;
        const lines = text.split(/\r\n|\n/);
        const newReadings = { ...readings };
        let count = 0;
        let nameIdx = -1, prevIdx = -1, currIdx = -1;

        if (lines.length > 0) {
            const header = lines[0].toLowerCase().split(/[;,]/).map(c => c.replace(/^"|"$/g, '').trim());
            nameIdx = header.findIndex(h => h.includes('sócio') || h.includes('nome') || h.includes('socio'));
            prevIdx = header.findIndex(h => h.includes('ant') || h.includes('anterior'));
            currIdx = header.findIndex(h => h.includes('atual'));
        }

        if (nameIdx === -1) nameIdx = 1; 
        if (prevIdx === -1) prevIdx = 5;
        if (currIdx === -1) currIdx = 6;

        lines.forEach((line, i) => {
            if (i === 0) return;
            if (!line.trim()) return;
            const cols = line.split(/[;,]/).map(c => c.replace(/^"|"$/g, '').trim());
            if (cols.length <= nameIdx) return;
            const name = cols[nameIdx];
            const prev = cols[prevIdx];
            const curr = cols[currIdx];
            const member = members.find(m => m.name.toLowerCase() === name.toLowerCase());
            if (member) {
                const existing = newReadings[member.id] || { previous: '', current: '' };
                if (prev && !isNaN(parseFloat(prev))) existing.previous = prev;
                if (curr && !isNaN(parseFloat(curr))) existing.current = curr;
                newReadings[member.id] = existing;
                count++;
            }
        });
        setReadings(newReadings);
        alert(`${count} leituras importadas!`);
    };
    reader.readAsText(file);
  };

  const handleMonthChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.value) {
          const [y, m] = e.target.value.split('-');
          const newDate = new Date(parseInt(y), parseInt(m) - 1, 1);
          setSelectedDate(newDate);
      }
  };

  const totalSystemStats = useMemo(() => {
    let totalConsumption = 0;
    let filledReadingsCount = 0;
    members.forEach(member => {
        const current = parseFloat(readings[member.id]?.current || '0');
        const previous = parseFloat(readings[member.id]?.previous || '0');
        if (readings[member.id]?.current) {
            filledReadingsCount++;
            const consumption = Math.max(0, current - previous);
            totalConsumption += consumption;
        }
    });
    return { totalConsumption, filledReadingsCount };
  }, [members, readings]);

  useEffect(() => {
      const billValue = parseFloat(energyBill);
      if (!isNaN(billValue) && billValue > 0 && totalSystemStats.totalConsumption > 0) {
          const calculatedPrice = billValue / totalSystemStats.totalConsumption;
          if (Math.abs(calculatedPrice - waterPrice) > 0.0001) {
             setWaterPrice(parseFloat(calculatedPrice.toFixed(4)));
          }
      }
  }, [energyBill, totalSystemStats.totalConsumption, setWaterPrice, waterPrice]);

  const calculateBill = (memberId: string) => {
    const current = parseFloat(readings[memberId]?.current || '0');
    const previous = parseFloat(readings[memberId]?.previous || '0');
    const consumption = Math.max(0, current - previous);
    const amount = (consumption * waterPrice) + serviceFee;
    return { consumption, amount };
  };

  const handleGenerateBills = (forceRecalculate = false) => {
    const dueDate = customDueDate; 
    let currentInvoiceCounter = startInvoiceNumber;
    const mapExistingInvoiceNumbers = new Map<string, number>();
    if (forceRecalculate) {
        existingBills.forEach(b => {
             if (b.invoiceNumber) mapExistingInvoiceNumbers.set(b.memberId, b.invoiceNumber);
        });
    }

    const newBills: MembershipDue[] = [];
    members.forEach(member => {
        if (readings[member.id]?.current) {
            const exists = dues.some(d => d.memberId === member.id && d.month === monthStr && d.year === year);
            if (exists && !forceRecalculate) return;

            const { consumption, amount } = calculateBill(member.id);
            const previous = parseFloat(readings[member.id]?.previous || '0');
            const current = parseFloat(readings[member.id]?.current || '0');

            const readingDetails: WaterReadingDetails = {
                previousReading: previous,
                currentReading: current,
                consumption: consumption,
                pricePerCubicMeter: waterPrice,
                serviceFee: serviceFee,
                referenceMonth: monthStr
            };

            let invoiceNum = mapExistingInvoiceNumbers.get(member.id);
            if (!invoiceNum) invoiceNum = currentInvoiceCounter++;

            const existingId = existingBills.find(b => b.memberId === member.id)?.id;
            const billId = existingId || `bill_${Date.now()}_${member.id}`;

            newBills.push({
                id: billId,
                memberId: member.id,
                memberName: member.name,
                memberAddress: member.address,
                month: monthStr,
                year: year,
                dueDate: dueDate,
                amount: parseFloat(amount.toFixed(2)),
                status: PaymentStatus.Pendente,
                readingDetails: readingDetails,
                invoiceNumber: invoiceNum 
            });
        }
    });

    if (newBills.length > 0) {
        if (forceRecalculate) onSyncDues(monthStr, year, newBills);
        else {
            onAddDues(newBills);
            setStartInvoiceNumber(currentInvoiceCounter);
        }
        setGeneratedDues(newBills);
        setIsInvoiceModalOpen(true);
    } else {
        alert("Nenhuma leitura preenchida para gerar faturas.");
    }
  };

  const handleGenerateClick = () => {
      if (existingBills.length > 0) {
          const confirm = window.confirm(`Já existem ${existingBills.length} faturas para ${monthStr}/${year}. Deseja RECALCULAR tudo?`);
          if (confirm) handleGenerateBills(true);
      } else {
          handleGenerateBills(false);
      }
  };

  const exportToCSV = () => {
      const billsToExport = generatedDues.length > 0 ? generatedDues : existingBills;
      if (billsToExport.length === 0) return;
      const csvHeader = "Nº Fatura;Sócio;Endereço;Referência;Vencimento;Leitura Ant.;Leitura Atual;Consumo m3;Valor R$;Status";
      const csvRows = billsToExport.map(bill => [
          bill.invoiceNumber || '',
          `"${bill.memberName}"`,
          `"${bill.memberAddress || ''}"`,
          `${bill.month}/${bill.year}`,
          new Date(bill.dueDate).toLocaleDateString('pt-BR'),
          bill.readingDetails?.previousReading || 0,
          bill.readingDetails?.currentReading || 0,
          bill.readingDetails?.consumption || 0,
          bill.amount.toFixed(2).replace('.', ','),
          bill.status
      ].join(';'));
      const csvContent = "\uFEFF" + [csvHeader, ...csvRows].join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `Faturas_Agua_${monthStr}_${year}.csv`;
      link.click();
  };

  const filteredMembers = members.filter(m => 
    m.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.cpf.includes(searchTerm)
  );

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
            <div>
                <h1 className="text-3xl font-bold text-gray-800 flex items-center gap-2">
                    <WaterDropIcon className="w-8 h-8 text-blue-500" />
                    Leitura de Hidrômetros ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS
                </h1>
                <p className="text-gray-500 text-sm mt-1">Gerencie leituras, calcule o rateio e emita faturas.</p>
            </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 mb-6">
            <h2 className="text-lg font-semibold text-gray-800 mb-6 flex items-center gap-2 border-b border-gray-100 pb-2">
                <CogIcon className="w-5 h-5 text-gray-500" />
                Painel de Controle
            </h2>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="space-y-4">
                    <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-3">Definições do Período</h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="group">
                            <label className="block text-xs font-semibold text-gray-500 mb-1.5 ml-1">Mês de Referência</label>
                            <div className="relative">
                                <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-blue-500 pointer-events-none" />
                                <input 
                                    type="month"
                                    value={`${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}`}
                                    onChange={handleMonthChange}
                                    className="block w-full pl-10 pr-3 py-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm font-semibold text-gray-800 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all focus:bg-white hover:border-blue-300"
                                />
                            </div>
                        </div>
                        <div className="group">
                            <label className="block text-xs font-semibold text-gray-500 mb-1.5 ml-1">Vencimento</label>
                            <input 
                                type="date"
                                value={customDueDate}
                                onChange={(e) => setCustomDueDate(e.target.value)}
                                className="block w-full px-3 py-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm font-semibold text-red-600 focus:ring-2 focus:ring-red-200 focus:border-red-500 transition-all focus:bg-white hover:border-red-300"
                            />
                        </div>
                         <div className="group">
                            <label className="block text-xs font-semibold text-gray-500 mb-1.5 ml-1">Nº Próx. Fatura</label>
                            <input 
                                type="number"
                                value={startInvoiceNumber}
                                onChange={(e) => setStartInvoiceNumber(parseInt(e.target.value))}
                                className="block w-full px-3 py-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm font-semibold text-gray-800 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all focus:bg-white"
                            />
                        </div>
                    </div>
                </div>

                <div className="space-y-4">
                    <h3 className="text-sm font-bold text-gray-400 uppercase tracking-wider mb-3">Cálculo Financeiro (Rateio)</h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div className="md:col-span-1">
                            <label className="block text-xs font-semibold text-green-700 mb-1.5 ml-1">Conta de Energia (R$)</label>
                            <div className="relative">
                                <DollarSignIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-green-600 pointer-events-none" />
                                <input 
                                    type="number" 
                                    step="0.01" 
                                    value={energyBill} 
                                    onChange={(e) => setEnergyBill(e.target.value)} 
                                    placeholder="0,00"
                                    className="block w-full pl-10 pr-3 py-2.5 bg-green-50 border border-green-200 rounded-lg text-sm font-bold text-green-800 focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-all placeholder-green-300" 
                                />
                            </div>
                        </div>
                         <div className="md:col-span-1">
                            <label className="block text-xs font-semibold text-gray-500 mb-1.5 ml-1">Preço do m³ (R$)</label>
                            <input 
                                type="number" 
                                step="0.0001" 
                                value={waterPrice} 
                                onChange={(e) => setWaterPrice(parseFloat(e.target.value))} 
                                className={`block w-full px-3 py-2.5 border rounded-lg text-sm font-bold focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all ${
                                    energyBill ? 'bg-yellow-50 border-yellow-300 text-yellow-800' : 'bg-gray-50 border-gray-200 text-gray-800'
                                }`}
                            />
                        </div>
                         <div className="md:col-span-1">
