// Helper function to get data from localStorage
const usePersistentState = <T,>(key: string, initialValue: T): [T, React.Dispatch<React.SetStateAction<T>>] => {
  const [state, setState] = useState<T>(() => {
    try {
      const storedValue = window.localStorage.getItem(key);
      return storedValue ? JSON.parse(storedValue) : initialValue;
    } catch (error) {
      console.error(`Error reading localStorage key “${key}”:`, error);
      return initialValue;
    }
  });

  useEffect(() => {
    try {
      window.localStorage.setItem(key, JSON.stringify(state));
    } catch (error) {
      console.error(`Error setting localStorage key “${key}”:`, error);
    }
  }, [key, state]);

  return [state, setState];
};


type View = 'dashboard' | 'members' | 'readings' | 'financials' | 'calendar' | 'backup';

interface NavItemProps {
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  onClick: () => void;
}

const NavItem: React.FC<NavItemProps> = ({ icon, label, isActive, onClick }) => (
    <button
        onClick={onClick}
        className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors duration-200 ${
            isActive
                ? 'bg-blue-700 text-white'
                : 'text-gray-200 hover:bg-blue-800 hover:text-white'
        }`}
    >
        {icon}
        <span className="ml-3">{label}</span>
    </button>
);


const App: React.FC = () => {
  const [activeView, setActiveView] = useState<View>('readings'); 

  // v4 force update to ensure initialDues are loaded
  const [members, setMembers] = usePersistentState<Member[]>('app_members_v4', initialMembers);
  const [dues, setDues] = usePersistentState<MembershipDue[]>('app_dues_v4', initialDues);
  const [expenses, setExpenses] = usePersistentState<Expense[]>('app_expenses_v4', initialExpenses);
  const [meetings, setMeetings] = usePersistentState<Meeting[]>('app_meetings_v4', initialMeetings);

  const [waterPrice, setWaterPrice] = usePersistentState<number>('app_water_price', DEFAULT_WATER_PRICE);
  const [serviceFee, setServiceFee] = usePersistentState<number>('app_service_fee', DEFAULT_SERVICE_FEE);

  const addMember = (memberData: Omit<Member, 'id'>) => {
    const newMember: Member = {
      id: `m_${Date.now()}`,
      ...memberData,
    };
    setMembers([...members, newMember]);
  };

  const updateMember = (updatedMember: Member) => {
    setMembers(prevMembers => prevMembers.map(m => m.id === updatedMember.id ? updatedMember : m));
  };

  const addExpense = (expenseData: Omit<Expense, 'id'>) => {
    const newExpense: Expense = {
      id: `e_${Date.now()}`,
      ...expenseData,
    };
    setExpenses(prevExpenses => [...prevExpenses, newExpense]);
  };

  const updateExpenseStatus = (expenseId: string, status: PaymentStatus) => {
    setExpenses(prevExpenses => 
      prevExpenses.map(exp => 
        exp.id === expenseId ? { ...exp, status } : exp
      )
    );
  };

  const updateDueStatus = (dueId: string, status: PaymentStatus) => {
    setDues(prevDues =>
      prevDues.map(due =>
        due.id === dueId ? { ...due, status, paymentDate: new Date().toISOString().split('T')[0] } : due
      )
    );
  };

  const addDues = (newDues: MembershipDue[]) => {
    setDues(prev => [...prev, ...newDues]);
  };

  const replaceMonthlyDues = (month: string, year: number, newDues: MembershipDue[]) => {
    setDues(prev => {
        const others = prev.filter(d => !(d.month === month && d.year === year));
        return [...others, ...newDues];
    });
  };

  const addMeeting = (meetingData: Omit<Meeting, 'id' | 'attendees' | 'minutes'>) => {
    const newMeeting: Meeting = {
      id: `meet_${Date.now()}`,
      ...meetingData,
      attendees: [],
    };
    setMeetings(prevMeetings => [...prevMeetings, newMeeting].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()));
  };

  const handleRestore = (data: {
    members: Member[];
    dues: MembershipDue[];
    expenses: Expense[];
    meetings: Meeting[];
  }) => {
    setMembers(data.members);
    setDues(data.dues);
    setExpenses(data.expenses);
    setMeetings(data.meetings);
  };

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard':
        return <DashboardPage members={members} dues={dues} meetings={meetings} />;
      case 'members':
        return <MembersPage members={members} onAddMember={addMember} onUpdateMember={updateMember} />;
      case 'readings':
        return <WaterReadingsPage 
                    members={members} 
                    dues={dues} 
                    onAddDues={addDues} 
                    onSyncDues={replaceMonthlyDues}
                    waterPrice={waterPrice}
                    serviceFee={serviceFee}
                    setWaterPrice={setWaterPrice}
                    setServiceFee={setServiceFee}
                />;
      case 'financials':
        return <FinancialsPage dues={dues} expenses={expenses} onUpdateExpenseStatus={updateExpenseStatus} onAddExpense={addExpense} onUpdateDueStatus={updateDueStatus} />;
      case 'calendar':
        return <CalendarPage meetings={meetings} onAddMeeting={addMeeting} />;
      case 'backup':
        return <BackupPage data={{ members, dues, expenses, meetings }} onRestore={handleRestore} />;
      default:
        return <DashboardPage members={members} dues={dues} meetings={meetings} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <DashboardIcon className="w-5 h-5"/> },
    { id: 'members', label: 'Sócios', icon: <UsersIcon className="w-5 h-5"/> },
    { id: 'readings', label: 'Leituras e Faturas', icon: <WaterDropIcon className="w-5 h-5"/> },
    { id: 'financials', label: 'Financeiro', icon: <DollarSignIcon className="w-5 h-5"/> },
    { id: 'calendar', label: 'Calendário', icon: <CalendarIcon className="w-5 h-5"/> },
  ];

  const settingsNavItem = {
    id: 'backup', label: 'Backup e Dados', icon: <CogIcon className="w-5 h-5" />
  };

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <aside className="w-64 bg-blue-900 text-white flex flex-col p-4">
        <div className="text-center py-4 mb-6">
          <h2 className="text-lg font-bold">ASSOCIAÇÃO COMUNITARIA UNIÃO DE SANTOS REIS</h2>
          <p className="text-xs text-blue-300">Gestão de Água</p>
        </div>
        <nav className="flex-1 flex flex-col justify-between">
            <div className="space-y-2">
                {navItems.map(item => (
                     <NavItem
                        key={item.id}
                        label={item.label}
                        icon={item.icon}
                        isActive={activeView === item.id}
                        onClick={() => setActiveView(item.id as View)}
                    />
                ))}
            </div>
            <div>
                <NavItem
                    key={settingsNavItem.id}
                    label={settingsNavItem.label}
                    icon={settingsNavItem.icon}
                    isActive={activeView === settingsNavItem.id}
                    onClick={() => setActiveView(settingsNavItem.id as View)}
                />
            </div>
        </nav>
      </aside>

      <main className="flex-1 overflow-y-auto">
        {renderContent()}
      </main>
    </div>
  );
};

