                                />
                            </div>
                        </div>
                         <div className="md:col-span-1">
                            <label className="block text-xs font-semibold text-gray-500 mb-1.5 ml-1">Preço do m³ (R$)</label>
                            <input 
                                type="number" 
                                step="0.0001" 
                                value={waterPrice} 
                                onChange={(e) => setWaterPrice(parseFloat(e.target.value))} 
                                className={`block w-full px-3 py-2.5 border rounded-lg text-sm font-bold focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all ${
                                    energyBill ? 'bg-yellow-50 border-yellow-300 text-yellow-800' : 'bg-gray-50 border-gray-200 text-gray-800'
                                }`}
                            />
                        </div>
                         <div className="md:col-span-1">
                            <label className="block text-xs font-semibold text-gray-500 mb-1.5 ml-1">Taxa Serviço (R$)</label>
                            <input 
                                type="number" 
                                step="0.01" 
                                value={serviceFee} 
                                onChange={(e) => setServiceFee(parseFloat(e.target.value))} 
                                className="block w-full px-3 py-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm font-medium text-gray-800 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all focus:bg-white" 
                            />
                        </div>
                    </div>
                    <div className="flex items-center gap-4 mt-2 bg-blue-50 p-3 rounded-lg border border-blue-100">
                         <div className="flex items-center gap-2">
                            <WaterDropIcon className="w-5 h-5 text-blue-500" />
