                         </div>
                         <span className="text-lg font-bold text-blue-700">{totalSystemStats.totalConsumption} m³</span>
                    </div>
                </div>
            </div>
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200 mb-6 flex flex-col xl:flex-row gap-4 items-center justify-between sticky top-0 z-40">
