                                    {member.name}
                                </td>
                                <td className="px-3 py-2 sticky left-[240px] z-20 bg-white group-even:bg-slate-50 group-hover:bg-blue-50 border-r border-gray-200 text-center">
                                    <input type="number" className="w-full h-11 px-3 border border-gray-300 rounded-lg text-right font-mono" value={readings[member.id]?.previous || ''} onChange={(e) => handleReadingChange(member.id, 'previous', e.target.value)} />
                                </td>
                                <td className="px-3 py-2 sticky left-[390px] z-20 bg-white group-even:bg-slate-50 group-hover:bg-blue-50 border-r border-gray-200 text-center">
                                    <input type="number" className="w-full h-11 px-3 border-2 border-blue-400 rounded-lg text-right font-bold font-mono" value={readings[member.id]?.current || ''} onChange={(e) => handleReadingChange(member.id, 'current', e.target.value)} />
                                </td>
                                <td className="px-8 py-3 text-center font-mono text-lg text-gray-700 border-r border-gray-200">{consumption}</td>
                                <td className="px-8 py-3 text-right font-bold text-lg text-gray-900 border-r border-gray-200">R$ {amount.toFixed(2)}</td>
                                <td className="px-8 py-3 text-center">
                                    {isGenerated ? <span className="px-3 py-1 text-xs font-bold rounded-full bg-green-100 text-green-700">GERADO</span> : <span className="px-3 py-1 text-xs font-semibold rounded-full bg-gray-100 text-gray-400">PENDENTE</span>}
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>

        <InvoiceModal isOpen={isInvoiceModalOpen} onClose={() => setIsInvoiceModalOpen(false)} dues={generatedDues} />
        <ReadingHistoryModal isOpen={!!selectedHistoryMember} onClose={() => setSelectedHistoryMember(null)} member={selectedHistoryMember} dues={dues} />
    </div>
  );
};

