    const totalEnergyBill = due.readingDetails?.totalEnergyBill ?? 0;
    const totalSystemConsumption = due.readingDetails?.totalSystemConsumption ?? 0;

    // Calculations
    const consumptionCost = consumption * price;
    const totalAmount = consumptionCost + serviceFee;

    const formattedAmount = formatCurrency(totalAmount).replace('R$', '').trim();
    const formattedRate = formatCurrency(price);
